export function getBrandMarkUrl(symbol) {
  if (typeof symbol !== "string") return null;
  const normalized = symbol.trim().toUpperCase();
  return BRAND_MARK_SYMBOLS.has(normalized) ? "/brand-marks/" + normalized + ".svg" : null;
}
